const makeFunctions = (
  profileId: string,
  count: number,
  baseTitle: string,
  descriptionSeed: string,
  relatedProcedureIds: string[] = [],
): FunctionItem[] =>
  Array.from({ length: count }, (_, index) => {
    const functionNumber = index + 1;
    const description =
      functionDescriptionOverrides[profileId]?.[functionNumber] ??
      `Función No. ${functionNumber} pendiente de transcripción exacta desde el Decreto 057 de 2018. No se relaciona automáticamente con procesos hasta validar su texto literal.`;

    return {
      id: `${profileId}-f${String(functionNumber).padStart(2, '0')}`,
      number: functionNumber,
      title: `${baseTitle} ${functionNumber}`,
      description,
      relatedProcedureIds,
      relationNote: relatedProcedureIds.length
        ? 'Relación calculada únicamente con reglas estrictas por función literal validada. No se usa afinidad amplia por dependencia.'
        : 'Sin relación automática con procedimientos. Requiere validación manual.',
    };
  });

const profile = (
  config: Omit<FunctionProfile, 'functions'> & {
    baseTitle: string;
    descriptionSeed: string;
    relatedProcedureIds?: string[];
  },
): FunctionProfile => ({
  ...config,
  functions: makeFunctions(
    config.id,
    config.functionCount,
    config.baseTitle,
    config.descriptionSeed,
    [],
  ),
});

